import { cn } from '@/lib/utils';
import { tv } from 'tailwind-variants';
import { IconLoader2 } from '@tabler/icons-react';

export interface ButtonProps {
  variant?: 'primary' | 'secondary' | 'gradient' | 'destructive';
  loader?: boolean;
  className?: string;
  size?: 'sm' | 'md' | 'lg';
  children: React.ReactNode;
  onClick?: () => void;
}

const buttonVariants = tv({
  base: 'font-medium bg-blue-500 text-white transition-colors inset-shadow-xs shadow-lg rounded-lg cursor-pointer inline-flex gap-2 items-center justify-center',
  variants: {
    color: {
      primary:
        'bg-neutral-950 hover:bg-neutral-900 border-1 border-neutral-800 inset-shadow-neutral-500',
      secondary:
        'bg-neutral-100 text-black hover:bg-neutral-200 dark:inset-shadow-sm inset-shadow-neutral-400',
      gradient:
        'bg-linear-65 from-purple-500 to-pink-500 rounded-full font-semibold hover:ring-1',
      destructive: 'bg-red-500 hover:bg-red-400 inset-shadow-neutral-400',
    },
    size: {
      sm: 'text-sm',
      md: 'text-base',
      lg: 'px-6 py-3 text-lg',
    },
  },
  compoundVariants: [
    {
      size: ['sm', 'md'],
      class: 'px-5 py-2',
    },
  ],
  defaultVariants: {
    size: 'md',
    color: 'primary',
  },
});

export const Button = ({
  variant,
  className,
  size,
  children,
  onClick,
  loader,
  ...props
}: ButtonProps) => {
  const loaderSizeMap: Record<'sm' | 'md' | 'lg', number> = {
    sm: 16,
    md: 18,
    lg: 20,
  };
  const loaderIconSize = loaderSizeMap[size ?? 'md'];

  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(buttonVariants({ size, color: variant }), className)}
      {...props}
    >
      {loader && (
        <span className="animate-spin">
          <IconLoader2 size={loaderIconSize} />
        </span>
      )}
      {children}
    </button>
  );
};

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
